p='src/cpu/mod.rs'
s=open(p).read()
s=s.replace("""    /// forced to 1S; the step after that continues sequentially as usual.
    fn charge_pipeline_refill""","""    /// forced to 1S; the step after that continues sequentially as usual.
    // ponytail: this totals 1S+1N per branch, one S short of gbatek's 2S+1N. Charging both
    // refetches (2S+1N) passes nba-hw dma-force-nseq-access but made spout-gameplay drift more
    // (0.312 vs 0.336); revisit once the Game Pak prefetch buffer and key latch timing land.
    fn charge_pipeline_refill""",1)
s=s.replace("""    #[test]
    fn branch_aligns_for_state() {""","""    #[test]
    fn branch_in_rom_charges_pipeline_refill() {
        // B . (0xEAFFFFFE) at 0x08000100, default WAITCNT: 16-bit ROM access N=5, S=3 cycles.
        let mut rom = vec![0; 0x200];
        rom[0x100..0x104].copy_from_slice(&0xEAFF_FFFEu32.to_le_bytes());
        let mut bus = Bus::new(&rom);
        let mut cpu = cpu_in_mode(MODE_SYSTEM);
        cpu.registers[PROGRAM_COUNTER] = 0x0800_0100;
        bus.read32(0x0800_00FC); // make the branch's own fetch sequential
        bus.take_access_cycles();
        // 1S own fetch (3+3) + 1N refill fetch of the target (5+3).
        assert_eq!(cpu.step(&mut bus), 6 + 8);
        assert_eq!(cpu.step(&mut bus), 6 + 8, "the target's own fetch is forced sequential");
    }

    #[test]
    fn branch_aligns_for_state() {""",1)
open(p,'w').write(s)
EOF
